// How do I create an animation that responds to user clicks in a presentation?

// Define an animation sequence that starts when a specific shape is clicked in a presentation.

const presentation = Api.GetPresentation();
const slide = presentation.GetSlideByIndex(0);

// Create trigger button
const button = Api.CreateShape(
	'roundRect',
	100 * 36000, 40 * 36000,
	Api.CreateSolidFill(Api.CreateRGBColor(0, 150, 0)),
	Api.CreateStroke(0, Api.CreateNoFill())
);
button.SetPosition(50 * 36000, 50 * 36000);
const buttonContent = button.GetDocContent();
const buttonPara = buttonContent.GetElement(0);
buttonPara.AddText('Click me!');
slide.AddObject(button);

// Create shape to animate
const animatedShape = Api.CreateShape(
	'star5',
	100 * 36000, 100 * 36000,
	Api.CreateSolidFill(Api.CreateRGBColor(255, 200, 0)),
	Api.CreateStroke(0, Api.CreateNoFill())
);
animatedShape.SetPosition(200 * 36000, 100 * 36000);
slide.AddObject(animatedShape);

// Create interactive sequence
const timeLine = slide.GetTimeLine();
const interactiveSeq = timeLine.AddInteractiveSequence(button);
interactiveSeq.AddEffect(animatedShape, 'emphasisSpin', 'onclick');

const infoShape = Api.CreateShape(
	'rect',
	200 * 36000, 30 * 36000,
	Api.CreateSolidFill(Api.CreateRGBColor(200, 200, 200)),
	Api.CreateStroke(0, Api.CreateNoFill())
);
infoShape.SetPosition(20 * 36000, 10 * 36000);
const content = infoShape.GetDocContent();
const paragraph = content.GetElement(0);
paragraph.AddText('Click the green button to spin the star!');
slide.AddObject(infoShape);

// How do I access the list of all animations on a slide in a presentation?

// Collect every animation effect that has been added to a presentation slide.

const presentation = Api.GetPresentation();
const slide = presentation.GetSlideByIndex(0);

// Create shapes
const shape1 = Api.CreateShape(
	'rect',
	100 * 36000, 80 * 36000,
	Api.CreateSolidFill(Api.CreateRGBColor(61, 74, 107)),
	Api.CreateStroke(0, Api.CreateNoFill())
);
shape1.SetPosition(50 * 36000, 80 * 36000);
slide.AddObject(shape1);

const shape2 = Api.CreateShape(
	'ellipse',
	100 * 36000, 80 * 36000,
	Api.CreateSolidFill(Api.CreateRGBColor(107, 61, 74)),
	Api.CreateStroke(0, Api.CreateNoFill())
);
shape2.SetPosition(180 * 36000, 80 * 36000);
slide.AddObject(shape2);

// Add animations
const timeLine = slide.GetTimeLine();
const mainSequence = timeLine.GetMainSequence();
mainSequence.AddEffect(shape1, 'entranceFade', 'onclick');
mainSequence.AddEffect(shape2, 'entranceFlyIn', 'afterprevious');

// Get all effects
const allEffects = timeLine.GetAllEffects();

const infoShape = Api.CreateShape(
	'rect',
	150 * 36000, 40 * 36000,
	Api.CreateSolidFill(Api.CreateRGBColor(200, 200, 200)),
	Api.CreateStroke(0, Api.CreateNoFill())
);
infoShape.SetPosition(20 * 36000, 10 * 36000);
const content = infoShape.GetDocContent();
const paragraph = content.GetElement(0);
paragraph.AddText('Total effects on slide: ' + allEffects.length);
slide.AddObject(infoShape);

// How do I find out what type of object a timeline is in a presentation?

// Get the class name identifier for a timeline in a presentation.

const presentation = Api.GetPresentation();
const slide = presentation.GetSlideByIndex(0);
const timeLine = slide.GetTimeLine();
const classType = timeLine.GetClassType();

const shape = Api.CreateShape(
	'rect',
	200 * 36000, 50 * 36000,
	Api.CreateSolidFill(Api.CreateRGBColor(61, 74, 107)),
	Api.CreateStroke(0, Api.CreateNoFill())
);
shape.SetPosition(100 * 36000, 100 * 36000);
const content = shape.GetDocContent();
const paragraph = content.GetElement(0);
paragraph.AddText('Class type: ' + classType);
slide.AddObject(shape);

// How do I access the interactive animations that respond to clicks in a presentation?

// Collect all animation sequences that are activated by user interactions in a presentation.

const presentation = Api.GetPresentation();
const slide = presentation.GetSlideByIndex(0);

// Create a trigger shape
const triggerShape = Api.CreateShape(
	'ellipse',
	80 * 36000, 80 * 36000,
	Api.CreateSolidFill(Api.CreateRGBColor(255, 100, 100)),
	Api.CreateStroke(0, Api.CreateNoFill())
);
triggerShape.SetPosition(50 * 36000, 100 * 36000);
slide.AddObject(triggerShape);

// Create animated shape
const animatedShape = Api.CreateShape(
	'rect',
	150 * 36000, 100 * 36000,
	Api.CreateSolidFill(Api.CreateRGBColor(61, 74, 107)),
	Api.CreateStroke(0, Api.CreateNoFill())
);
animatedShape.SetPosition(180 * 36000, 100 * 36000);
slide.AddObject(animatedShape);

const timeLine = slide.GetTimeLine();

// Create interactive sequence triggered by clicking the red circle
const interactiveSeq = timeLine.AddInteractiveSequence(triggerShape);
interactiveSeq.AddEffect(animatedShape, 'entranceFlyIn', 'onclick');

const sequences = timeLine.GetInteractiveSequences();

const infoShape = Api.CreateShape(
	'rect',
	200 * 36000, 40 * 36000,
	Api.CreateSolidFill(Api.CreateRGBColor(200, 200, 200)),
	Api.CreateStroke(0, Api.CreateNoFill())
);
infoShape.SetPosition(20 * 36000, 10 * 36000);
const content = infoShape.GetDocContent();
const paragraph = content.GetElement(0);
paragraph.AddText('Interactive sequences count: ' + sequences.length);
slide.AddObject(infoShape);

// How do I get the default animation list for a slide in a presentation?

// Retrieve the main timeline sequence where automatic animations are placed in a presentation.

const presentation = Api.GetPresentation();
const slide = presentation.GetSlideByIndex(0);

const shape = Api.CreateShape(
	'rect',
	150 * 36000, 100 * 36000,
	Api.CreateSolidFill(Api.CreateRGBColor(61, 74, 107)),
	Api.CreateStroke(0, Api.CreateNoFill())
);
shape.SetPosition(100 * 36000, 100 * 36000);
slide.AddObject(shape);

const timeLine = slide.GetTimeLine();
const mainSequence = timeLine.GetMainSequence();

// Add a fade effect
mainSequence.AddEffect(shape, 'entranceFade', 'onclick');

const infoShape = Api.CreateShape(
	'rect',
	150 * 36000, 40 * 36000,
	Api.CreateSolidFill(Api.CreateRGBColor(200, 200, 200)),
	Api.CreateStroke(0, Api.CreateNoFill())
);
infoShape.SetPosition(20 * 36000, 10 * 36000);
const content = infoShape.GetDocContent();
const paragraph = content.GetElement(0);
paragraph.AddText('Effects in sequence: ' + mainSequence.GetCount());
slide.AddObject(infoShape);
